dtsPropsFor.Art:
/** Colour and motif record the SVG scene is generated from. */
art: {
  /** Background base colour, hex. */
  sky?: string;
  /** Foreground / highlight colour, hex. */
  accent?: string;
  /** Which scene to draw. Undrawn motifs fall through to the stripe placeholder. */
  motif?:
    | 'brass' | 'mural' | 'rowhouse' | 'skyline' | 'oak'
    | 'waves' | 'palm' | 'dune' | 'ferry' | 'ridge';
};
/** Names the photograph this art stands in for. Rendered as a monospace chip
 *  and used as the SVG's accessible label, so it is required. */
caption: string;
/** 'art--tall' (3:4) or 'art--wide' (16:9). Omit for the 4:3 default.
 *  Shape comes from CSS — Art fills whatever box it is given. */
className?: string;

dtsPropsFor.EstimateBadge:
/** Label text. Defaults to 'Estimated prototype data'.
 *  Must stay visible anywhere a price appears — every price in this app
 *  is invented, and the badge is what says so. */
children?: React.ReactNode;

dtsPropsFor.Button:
/** 'primary' is the solid coral fill — at most one per screen. */
variant?: 'default' | 'primary' | 'ghost';
/** Full width. */
block?: boolean;
/** Defaults to 'button', not 'submit'. */
type?: 'button' | 'submit' | 'reset';
disabled?: boolean;
onClick?: React.MouseEventHandler<HTMLButtonElement>;
className?: string;
children?: React.ReactNode;

dtsPropsFor.Chip:
/** 'match' is the coral % score (one per card). 'risk' is gold and names
 *  what a saving costs you — never decorative. */
tone?: 'neutral' | 'match' | 'risk';
className?: string;
children?: React.ReactNode;

dtsPropsFor.Card:
/** Unpadded on purpose — it clips its children so Art can run edge to
 *  edge. Put content in CardBody. */
className?: string;
children?: React.ReactNode;

dtsPropsFor.CardBody:
/** The padded, vertically-stacked region under a card's art. */
className?: string;
children?: React.ReactNode;

dtsPropsFor.Field:
/** Rendered above the control, inside the <label>. */
label: string;
/** A NATIVE <input> or <select> — index.css styles those globally. */
children: React.ReactNode;
className?: string;

dtsPropsFor.Segmented:
/** Keep to 2-4. Past that, use a <select> inside a Field. */
options: { value: string | number; label: string }[];
value: string | number;
onChange: (value: string | number) => void;
/** Names the group for assistive tech. */
ariaLabel?: string;
className?: string;
